namespace Game_Catalog.Models
{
    /// <summary> Represents a user-defined tag for classifying games. </summary>
    public class Tag
    {
        /// <summary> Unique identifier of the tag. Generated by the database. </summary>
        public int TagId { get; set; }

        private string _tagName = string.Empty;
        /// <summary> Name of the tag. </summary>
        public string TagName
        {
            get => _tagName;
            set => _tagName = value ?? string.Empty;
        }

        private string _color = string.Empty;
        /// <summary> Palette key of the tag color (for example "Red"). Empty means no color. </summary>
        public string Color
        {
            get => _color;
            set => _color = value ?? string.Empty;
        }
    }
}